package com.tencent.weknora.security;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.util.*;import java.util.stream.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class InvitationRequestDecoderCompatibilityTest {
    @TestFactory Stream<DynamicTest> actualGoHandlerBodies()throws Exception{ObjectMapper json=new ObjectMapper();JsonNode fixture=json.readTree(Files.readString(Path.of("src/test/java/com/tencent/weknora/security/invitation-binding-golden.json")));List<DynamicTest> tests=new ArrayList<>();for(JsonNode row:fixture)tests.add(DynamicTest.dynamicTest(row.path("schema").asText()+"/"+row.path("name").asText(),()->{byte[] raw=Base64.getDecoder().decode(row.path("raw").asText());var schema=InvitationRequestDecoder.Schema.valueOf(row.path("schema").asText());JsonNode error=row.path("body").path("error");if(error.path("code").asInt()==1010&&!error.path("details").isNull()){ApiException actual=assertThrows(ApiException.class,()->InvitationRequestDecoder.decode(raw,schema));assertEquals(row.path("status").asInt(),actual.status());assertEquals(error.path("code").asInt(),actual.appCode());assertEquals(error.path("message").asText(),actual.getMessage());assertEquals(error.path("details").asText(),actual.details());}else{Map<String,Object> decoded=assertDoesNotThrow(()->InvitationRequestDecoder.decode(raw,schema));assertEquals(new HashSet<>(schema.fields),decoded.keySet());if(row.path("name").asText().equals("invalid-utf8")||row.path("name").asText().equals("surrogate"))assertEquals("\ufffd",decoded.get(schema.fields.getFirst()));if(row.path("name").asText().endsWith("-duplicate-null")){String field=row.path("name").asText().replace("-duplicate-null","");assertFalse(((String)decoded.get(field)).isEmpty());}}}));return tests.stream();}
}
